
(function(){
  const qs=(s,c=document)=>c.querySelector(s), qsa=(s,c=document)=>[...c.querySelectorAll(s)];
  const store={get:(k)=>{try{return localStorage.getItem(k)}catch(e){return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}}};
  const toast=qs('#toast');
  window.showToast=(title,msg='')=>{if(!toast)return;toast.innerHTML=`<strong>${title}</strong>${msg}`;toast.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>toast.classList.remove('show'),3600)};
  const menu=qs('#mobileNav'), menuBtn=qs('#menuBtn');
  if(menu&&menuBtn){menuBtn.addEventListener('click',()=>{const open=menu.classList.toggle('open');menuBtn.setAttribute('aria-expanded',open?'true':'false');document.body.style.overflow=open?'hidden':''});}
  qsa('[data-faq-button]').forEach(b=>b.addEventListener('click',()=>{const a=document.getElementById(b.getAttribute('aria-controls'));const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',open?'false':'true');a.classList.toggle('open',!open)}));
  const faqSearch=qs('#faqSearch');
  function filterFaq(){if(!faqSearch)return;const term=faqSearch.value.toLowerCase().trim();const active=qs('.chip.active')?.dataset.category||'all';qsa('.faq-group').forEach(g=>{let visible=0;qsa('.faq',g).forEach(row=>{const hay=row.textContent.toLowerCase();const cat=g.dataset.category;const okCat=active==='all'||cat===active;const ok=okCat&&(!term||hay.includes(term));row.classList.toggle('hidden',!ok);if(ok)visible++});g.classList.toggle('hidden',visible===0)});}
  if(faqSearch){faqSearch.addEventListener('input',filterFaq);qsa('.chip[data-category]').forEach(c=>c.addEventListener('click',()=>{qsa('.chip[data-category]').forEach(x=>x.classList.remove('active'));c.classList.add('active');filterFaq()}));}
  const contact=qs('#contactForm');
  if(contact){contact.addEventListener('submit',e=>{e.preventDefault();let bad=false;qsa('[required]',contact).forEach(i=>{if(!i.value.trim()){bad=true;i.closest('.field')?.classList.add('error')}else{i.closest('.field')?.classList.remove('error')}});if(bad){showToast('Please check the form','Required fields are still empty.');return;}contact.reset();const cs=qs('#contactSuccess');if(cs){cs.classList.remove('hidden');cs.style.display='block'}showToast('Message received','Prototype success state shown. No message was actually sent.');});}
  const track=qs('#trackForm');
  if(track){track.addEventListener('submit',e=>{e.preventDefault();const order=qs('#trackOrder').value.trim();const phone=qs('#trackPhone').value.trim();if(!order||!phone){qs('#trackError').style.display='block';qs('#trackingResult').classList.remove('open');return;}if(order.toLowerCase().includes('invalid')){qs('#trackError').style.display='block';qs('#trackingResult').classList.remove('open');return;}qs('#trackError').style.display='none';qs('#trackingResult').classList.add('open');qs('#demoOrder').textContent=order;showToast('Order found','Showing a prototype shipment state.');});}
  let qty=1; const qtyEl=qs('#qtyValue'), subtotal=qs('#subtotal'), total=qs('#cartTotal'), finish=qs('#frameFinish');
  const prices={'Antique Gold':23900,'Gold':20900,'Black':18900,'White':18900};
  function money(n){return '₹'+n.toLocaleString('en-IN')}
  function updateCart(){const p=prices[finish?.value||'Antique Gold']||23900; if(qtyEl)qtyEl.textContent=qty;if(subtotal)subtotal.textContent=money(p*qty);if(total)total.textContent=money(p*qty);store.set('aalishaanDemoCart',JSON.stringify({qty,finish:finish?.value||'Antique Gold',price:p}));const count=qs('#cartCount');if(count)count.textContent=qty;}
  qs('#qtyMinus')?.addEventListener('click',()=>{qty=Math.max(1,qty-1);updateCart()});qs('#qtyPlus')?.addEventListener('click',()=>{qty=Math.min(9,qty+1);updateCart()});finish?.addEventListener('change',()=>{updateCart();showToast('Frame updated','Prototype price updated for layout testing only.')});
  qs('#removeItem')?.addEventListener('click',()=>{qs('#cartItem').style.display='none';qs('#cartSummary').style.opacity='.45';showToast('Artwork removed','Reload this page to restore the prototype item.')});
  const saved=JSON.parse(store.get('aalishaanDemoCart')||'null'); if(saved){qty=saved.qty||1;if(finish)finish.value=saved.finish||'Antique Gold'} updateCart();
  const pin=qs('#pincode'); pin?.addEventListener('blur',()=>{const out=qs('#pinResult');if(!out)return; if(/^\d{6}$/.test(pin.value)){out.textContent='Serviceability check: prototype success state · Estimated arrival will be confirmed before launch.';out.className='notice success'}else if(pin.value){out.textContent='Enter a valid six-digit Indian pincode.';out.className='notice error'}});
  const checkout=qs('#checkoutForm');
  if(checkout){const data=JSON.parse(store.get('aalishaanDemoCart')||'{}');qsa('[data-cart-finish]').forEach(x=>x.textContent=data.finish||'Antique Gold');qsa('[data-cart-price]').forEach(x=>x.textContent=money((data.price||23900)*(data.qty||1)));checkout.addEventListener('submit',e=>{e.preventDefault();let bad=false;qsa('[required]',checkout).forEach(i=>{if((i.type==='checkbox'||i.type==='radio')?!i.checked:!i.value.trim()){bad=true;i.closest('.field,.pay-option')?.classList.add('error')}else{i.closest('.field,.pay-option')?.classList.remove('error')}});if(bad){showToast('Review required fields','Nothing has been charged.');return;}const processing=qs('#processing');processing?.classList.add('open');setTimeout(()=>{store.set('aalishaanDemoOrder',JSON.stringify({order:'AS-DEMO-2408',finish:data.finish||'Antique Gold',qty:data.qty||1,total:(data.price||23900)*(data.qty||1)}));location.href='../order/demo/index.html';},1500)});}
  const order=JSON.parse(store.get('aalishaanDemoOrder')||'{}');qsa('[data-order-number]').forEach(x=>x.textContent=order.order||'AS-DEMO-2408');qsa('[data-order-finish]').forEach(x=>x.textContent=order.finish||'Antique Gold');qsa('[data-order-total]').forEach(x=>x.textContent=money(order.total||23900));
  const cookieDialog=qs('#cookieDialog');function openCookie(){cookieDialog?.classList.add('open');qs('#cookieDialog .dialog-close')?.focus()}function closeCookie(){cookieDialog?.classList.remove('open')};qsa('[data-cookie-open]').forEach(b=>b.addEventListener('click',openCookie));qsa('[data-cookie-close]').forEach(b=>b.addEventListener('click',closeCookie));qsa('[data-cookie-save]').forEach(btn=>btn.addEventListener('click',()=>{const scope=btn.closest('.dialog,.policy-content')||document;store.set('aalishaanCookiePrefs',JSON.stringify({analytics:qs('[data-cookie-analytics]',scope)?.checked||false,ads:qs('[data-cookie-ads]',scope)?.checked||false}));if(btn.closest('.dialog'))closeCookie();showToast('Preferences saved','Prototype preference state stored in this browser.')}));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(menu?.classList.contains('open')){menu.classList.remove('open');menuBtn?.setAttribute('aria-expanded','false');document.body.style.overflow='';menuBtn?.focus()}if(cookieDialog?.classList.contains('open'))closeCookie()}});
  const sections=qsa('.policy-content section[id]'), toc=qsa('.toc a');if(sections.length&&'IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>{entries.forEach(en=>{if(en.isIntersecting){toc.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+en.target.id))}})},{rootMargin:'-20% 0px -70% 0px'});sections.forEach(s=>obs.observe(s));}
})();
